import{_ as t,c as i,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易纬辨终备〔汉〕郑玄","description":"易纬辨终备 - 易纬辨终备〔汉〕郑玄","frontmatter":{"title":"易纬辨终备〔汉〕郑玄","description":"易纬辨终备 - 易纬辨终备〔汉〕郑玄"},"headers":[],"relativePath":"zh/classics/yiwei-bianzhongbei/001.md","filePath":"zh/classics/yiwei-bianzhongbei/001.md"}'),r={name:"zh/classics/yiwei-bianzhongbei/001.md"};function o(c,a,l,d,p,h){return s(),i("div",null,[...a[0]||(a[0]=[e("h1",{id:"易纬辨终备〔汉〕郑玄",tabindex:"-1"},[n("易纬辨终备〔汉〕郑玄 "),e("a",{class:"header-anchor",href:"#易纬辨终备〔汉〕郑玄","aria-label":"Permalink to “易纬辨终备〔汉〕郑玄”"},"​")],-1),e("p",null,"钦定四库全书易纬辨终备 ​汉 郑康成 注孔子表河图皇参持曰：天以斗视，日发明，皇以戏招始，挂八卦谈。 ​皇参持，河图名也。言以北斗之星视听，而以日月发其明，以昭示天地。三皇伏戏始卦，以示后世之人，谓使观见之矣。煌煌之燿，乾为之冈。合凝之类，坤握其方。 ​煌煌，光辉之貌。燿，日月五星也。皆以乾冈图言，尽系于天也。方，道也。合凝，为首形之类，坤则握其道，皆系于地也。雄雌呿吟，六节摇通。 ​雄雌，天地。呿吟，阖闭也。六节，六子也。摇通，言六子动行天地之气。系曰：「闭户谓之坤，辟户谓之乾。」又曰：天地定位，山泽通气也。万物孳甲，曰营始东。 ​孳，生也。甲，东方之行，物所生，故数以始也。三五环复，七十六载闰反常。 ​三五千百二十岁，历历复其本，七十六载则余分尽。言天终则后始者耳也。旋出枢，乾机据参衡出坤，离，授提巽招震夘， ​乾正。旋、枢、衡、招皆北星，值乾君之象。旋星出枢之政教。机，正，机之发动，故其位据。参，西方之宿。五事五方为言，犹君出政之言也。玉衡之星，言主布天之手法，于坤离授明，提巽招震之职权，君平事之臣。夘，东方之宿也。○按五事五方与正文不相应，疑有脱文。纬嬴缩，辰中效当。 ​纬，五纬。盈缩，行有进退也。辰，星。仲，谓夘酉子午。候星辰之常，以四仲之月视其效当与不也。必视荧惑所在时殃。 ​荧惑主理天下，故必候之，以知时祸。循岁德，镇之光。 ​镇主章存德，故候星之光，以故德之所在也。拒白甄商，金大谋兵。 ​拒白，太白之主杀罚，而金宿，故甄商金声，言太白大为众之候，元武兵大谋之也。雪霜，水疾，旱饥，丧，地动，山崩沦，慧陨，物吝悖淫。 ​崩沦，若步庶崩者也。慧，彗。陨，陨石也，立社稷之类。悖，见。淫，散也。负之傍害，水决，江德溃，河空移徙，赤黄。 ​负之示闻。傍，水决貌。江德溃，亦谓决乱而出也。空，竭之。移徙，地震之类也。踊起，物怪踊跃出见，以日昴冲望之，曰乘阴气。○按「示闻」二字疑误，「踊起」以下与正文不相应，疑有脱文。箕风飘石折，拔树酷深。 ​酷，暴也。飘石折树，言繋夹也。暴深，害物甚也。长大卒嬉，暴大杨。 ​暴大，言不以渐。杨杨，大貌也。解裂珥偶，虹霓孽行。 ​解，陷也，沦也。裂，地圯。珥偶、虹霓，皆日傍气名妖。沉藏相桐，水害□滂滂。 ​沉藏，当藏以物。相，当为桐。射发立也。滂滂，水貌也。日之既，阳德消。月之毁，刑将将。 ​日既，日蚀，明尽，故阳消。月之毁，亦谓月蚀常过也。阴将，将，大也。阴主刑，阴似脱之大怪。土蒙，群鸟却，野兽群，游人孳。 ​来济者，来成也。其气不效，君不能修德杜渐防萌。黄雾满者，乱气起也。朝方阳，埃寇将来，十刃之，莫四出，虻牛招尸，益士与之开。皆离坎之异也。鳞出者，圣人将起，授之符纬。有王者则聚生五帝之坐。其帝将王，则其坐亡光也。○按此注皆与正文不相合，疑有脱简。按录视天，比象由。 ​按录，按河图之录，又视按王光之异，比其象以观其光由，起也。神灵悉存，八八通时， ​在，察也。神灵，三光异及符瑞也。既按三光之异及符瑞，以知起者所由，以六十四卦通，其谓以何？○按正文无「在」字，而注言「在，察也」，亦疑有脱文。小辨终备，无遗戒。郄知亿，察世邮。 ​世邮，郄变也。帝王奉命，永安治。 ​命，犹书也。至哉易，三圣谋，专密恶，必孰思。 ​三圣：伏羲、文王、孔子。○按史记张守节正义引易中备云：「孔子正月为商瞿筮，曰：瞿当有五丈夫子。子贡曰：何以知之？子曰：卦遇大畜，艮之二世，九二甲寅木为世，九五景子水为应，阳爻五，应有五子云云。」检今书无其文，盖非全本也。自伏羲以来，汉永和元年，凡四十万九千三百八十九岁。 ​按：此为后人所加，非易纬本文。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
